from itertools import product
from fractions import Fraction
import json

# Partitions are decreasing tuples; all parts are positive.
def parts_box(r,q):
    out=[]
    def rec(last, left, cur):
        out.append(tuple(cur))
        if left:
            for x in range(min(last,q),0,-1): rec(x,left-1,cur+[x])
    # generate cleanly, excluding empty below
    def gen(maxpart, maxlen, prefix):
        out.append(tuple(prefix))
        if len(prefix)<maxlen:
            for x in range(min(maxpart, prefix[-1] if prefix else maxpart),0,-1):
                gen(x,maxlen,prefix+[x])
    out=[]; gen(q,r,[])
    return sorted(set(out),key=lambda x:(sum(x),x))
def contains(mu,lam): # mu contains lam
    return all((mu[i] if i<len(mu) else 0)>=x for i,x in enumerate(lam))
def sz(p): return sum(p)
def lab(p): return ''.join(map(str,p)) if p else '0'
R=Q=3; rect=(2,2)
allp=parts_box(R,Q)
J=[p for p in allp if contains(p,rect)]
bydeg={d:[p for p in J if sz(p)==d] for d in range(4,10)}

# horizontal strip test nu/mu: interlacing nu_1>=mu_1>=nu_2>=mu_2 ...
def horiz(mu,nu):
    if not contains(nu,mu): return False
    L=max(len(mu),len(nu))
    for i in range(L):
        mi=mu[i] if i<len(mu) else 0
        nj=nu[i+1] if i+1<len(nu) else 0
        if mi<nj: return False
    return True
def pieri(mu,k):
    return [nu for nu in J if sz(nu)==sz(mu)+k and horiz(mu,nu)]

# Independent tableau enumerator for c_{lam,mu}^{nu}: fill nu/lam in LR reading order.
def lrcoef(lam,mu,nu):
    if not contains(nu,lam) or sz(nu)-sz(lam)!=sz(mu): return 0
    cells=[]
    for i in range(len(nu)):
        start=lam[i] if i<len(lam) else 0
        for j in range(nu[i],start,-1): # right to left
            cells.append((i+1,j))
    content={v:mu[v-1] for v in range(1,len(mu)+1)}
    filled={}; used={v:0 for v in content}; ans=0
    def go(t):
        nonlocal ans
        if t==len(cells): ans+=1; return
        i,j=cells[t]
        # row neighbor right has already been filled; require x <= right.
        right=filled.get((i,j+1))
        # above cell may be filled (earlier row); column strict: above < x.
        above=filled.get((i-1,j))
        for x in content:
            if used[x]>=content[x]: continue
            if right is not None and x>right: continue
            if above is not None and above>=x: continue
            # lattice after appending x: count(x-1) >= count(x), x>1
            if x>1 and used.get(x-1,0) < used[x]+1: continue
            filled[(i,j)]=x; used[x]+=1; go(t+1); used[x]-=1; del filled[(i,j)]
    go(0); return ans

# Vectors by degree columns in displayed order.
def vec_pieri(mu,k,d):
    cols=bydeg[d]; return [1 if x in pieri(mu,k) else 0 for x in cols]
def vec_lr(lam,mu,d):
    return [lrcoef(lam,mu,nu) for nu in bydeg[d]]

# Explicit certificate rows, with free columns F1 = 22,32,33.
selected={
5:[((2,2),1)],
