free={(2,2),(3,2),(3,3)}

def det(A):
    n=len(A)
    if n==0:return 1
    M=[[Fraction(x) for x in row] for row in A]; v=Fraction(1)
    for c in range(n):
        p=next((i for i in range(c,n) if M[i][c]),None)
        if p is None:return 0
        if p!=c:M[c],M[p]=M[p],M[c];v=-v
        z=M[c][c];v*=z
        for i in range(c+1,n):
            if M[i][c]:
                a=M[i][c]/z
                for j in range(c,n):M[i][j]-=a*M[c][j]
    return int(v)
def solve_rowcomb(rows,v): # solve x*rows=v, rational exact
    m=len(rows); n=len(v)
    A=[[Fraction(rows[i][j]) for i in range(m)] + [Fraction(v[i])] for j in range(n)] # transpose augmented
    # Gaussian solve m unknowns; rows assumed independent, redundant equations okay
    piv=[]; rr=0
    for c in range(m):
        p=next((i for i in range(rr,n) if A[i][c]),None)
        if p is None: raise ValueError('rank')
        A[rr],A[p]=A[p],A[rr]; z=A[rr][c]; A[rr]=[x/z for x in A[rr]]
        for i in range(n):
            if i!=rr and A[i][c]:
                z=A[i][c]; A[i]=[A[i][j]-z*A[rr][j] for j in range(m+1)]
        piv.append(rr);rr+=1
    x=[A[piv[c]][m] for c in range(m)]
    if any(sum(x[i]*rows[i][j] for i in range(m))!=v[j] for j in range(n)):raise ValueError('no solution')
    if any(y.denominator!=1 for y in x):raise ValueError('nonintegral')
    return [int(y) for y in x]

certificate=[]; all_pieri_reductions=[]; all_lr_reductions=[]; total_pieri=0; total_lr=0
for d in range(5,10):
    cols=bydeg[d]
    rows=[vec_pieri(mu,k,d) for mu,k in selected[d]]
    nonfree=[x for x in cols if x not in free]
    idx=[cols.index(x) for x in nonfree]
    minor=[[row[j] for j in idx] for row in rows]
    certificate.append({'degree':d,'columns':[lab(x) for x in cols],'free_columns':[lab(x) for x in cols if x in free],
                        'selected_rows':[lab(mu)+';'+str(k) for mu,k in selected[d]],'minor':minor,'determinant':det(minor)})
    for mu in J:
        for k in range(1,Q+1):
            if sz(mu)+k==d:
                v=vec_pieri(mu,k,d)
                if any(v):
                    total_pieri+=1
                    all_pieri_reductions.append({'degree':d,'row':lab(mu)+';'+str(k),'vector':v,'coordinates':solve_rowcomb(rows,v)})
    for lam in allp:
        if not lam: continue
        for mu in J:
            if sz(lam)+sz(mu)==d:
                v=vec_lr(lam,mu,d)
                if any(v):
                    total_lr+=1
                    all_lr_reductions.append({'degree':d,'row':lab(lam)+'*'+lab(mu),'vector':v,'coordinates':solve_rowcomb(rows,v)})
